package gotifyproxy

import (
	"bytes"
	"io"
	"net/http"
	"net/http/httputil"
	"net/url"
	"strconv"
	"strings"
	"sync"
	"time"
)

const UIPrefix = "/g"

// sessionCookieMaxAge matches Gotify v3 auth.CookieMaxAge (7 days).
const sessionCookieMaxAge = 7 * 24 * 60 * 60

// Proxy reverse-proxies Gotify through the local Wails asset server so the
// embedded UI shares origin with the desktop shell and can stay authenticated
// via the client token (injected as X-Gotify-Key / Cookie).
type Proxy struct {
	mu     sync.RWMutex
	target *url.URL
	token  string
}

// Update sets the upstream Gotify base URL and client token.
func (p *Proxy) Update(serverURL, token string) error {
	p.mu.Lock()
	defer p.mu.Unlock()
	if serverURL == "" || token == "" {
		p.target = nil
		p.token = ""
		return nil
	}
	u, err := url.Parse(serverURL)
	if err != nil {
		return err
	}
	p.target = u
	p.token = REDACTED
	return nil
}

// Middleware returns a Wails AssetServer middleware.
func (p *Proxy) Middleware(next http.Handler) http.Handler {
	return http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		if !p.shouldProxy(r) {
			next.ServeHTTP(w, r)
			return
		}
		p.serve(w, r)
	})
}

func (p *Proxy) shouldProxy(r *http.Request) bool {
	p.mu.RLock()
	ready := p.target != nil && p.token != ""
	p.mu.RUnlock()
	if !ready {
		return false
	}
	path := r.URL.Path
	if path == UIPrefix || strings.HasPrefix(path, UIPrefix+"/") {
		return true
	}
	return isGotifyAPIPath(path)
}

func isGotifyAPIPath(path string) bool {
	prefixes := []string{
		"/current/",
		"/message",
		"/application",
		"/client",
		"/plugin",
		"/stream",
		"/auth/",
		"/health",
		"/version",
		"/image/",
		"/static/",
		"/swagger",
		"/docs",
		"/mcp",
	}
	for _, prefix := range prefixes {
		if path == strings.TrimSuffix(prefix, "/") || strings.HasPrefix(path, prefix) {
			return true
		}
	}
	return false
}

func (p *Proxy) serve(w http.ResponseWriter, r *http.Request) {
	p.mu.RLock()
	target := *p.target
	token := p.token
	p.mu.RUnlock()

	path := r.URL.Path
	uiRequest := path == UIPrefix || strings.HasPrefix(path, UIPrefix+"/")
	if path == UIPrefix {
		path = "/"
	} else if strings.HasPrefix(path, UIPrefix+"/") {
		path = strings.TrimPrefix(path, UIPrefix)
		if path == "" {
			path = "/"
		}
	}

	proxy := httputil.NewSingleHostReverseProxy(&target)
	originalDirector := proxy.Director
	proxy.Director = func(req *http.Request) {
		originalDirector(req)
		req.URL.Scheme = target.Scheme
		req.URL.Host = target.Host
		req.URL.Path = path
		req.Host = target.Host
		// Avoid gzip so HTML injection can rewrite the body safely.
		req.Header.Del("Accept-Encoding")
		req.Header.Set("X-Gotify-Key", token)
		req.Header.Set("Authorization", "Bearer "+token)
		req.Header.Set("Cookie", "gotify-client-token=REDACTED
		// Gotify's web UI opens /stream without ?token= and relies on the cookie.
		// Ensure the upstream stream always receives the token explicitly.
		if path == "/stream" || strings.HasPrefix(path, "/stream/") {
			q := req.URL.Query()
			if q.Get("token") == "" {
				q.Set("token", token)
				req.URL.RawQuery = q.Encode()
			}
		}
		req.Header.Del("Origin")
		req.Header.Del("Referer")
	}
	proxy.ModifyResponse = func(resp *http.Response) error {
		resp.Header.Del("X-Frame-Options")
		resp.Header.Del("Content-Security-Policy")
		// Drop upstream cookies; we set a single session cookie ourselves.
		resp.Header.Del("Set-Cookie")
		setSessionCookie(resp.Header, token)

		if loc := resp.Header.Get("Location"); loc != "" {
			if u, err := url.Parse(loc); err == nil {
				if u.Host == "" || strings.EqualFold(u.Host, target.Host) {
					u.Scheme = ""
					u.Host = ""
					locPath := u.Path
					if locPath == "" || locPath == "/" {
						resp.Header.Set("Location", UIPrefix+"/")
					} else if isGotifyAPIPath(locPath) {
						resp.Header.Set("Location", u.String())
					} else {
						u.Path = UIPrefix + locPath
						resp.Header.Set("Location", u.String())
					}
				}
			}
		}

		if uiRequest && strings.Contains(resp.Header.Get("Content-Type"), "text/html") && resp.Body != nil {
			body, err := io.ReadAll(io.LimitReader(resp.Body, 2<<20))
			_ = resp.Body.Close()
			if err != nil {
				return err
			}
			body = injectSessionBootstrap(body, token)
			resp.Header.Del("Content-Encoding")
			resp.Body = io.NopCloser(bytes.NewReader(body))
			resp.Header.Set("Content-Length", strconv.Itoa(len(body)))
			resp.ContentLength = int64(len(body))
		}
		return nil
	}
	proxy.ErrorHandler = func(rw http.ResponseWriter, req *http.Request, err error) {
		http.Error(rw, "gotify proxy error: "+err.Error(), http.StatusBadGateway)
	}
	proxy.ServeHTTP(w, r)
}

func setSessionCookie(h http.Header, token string) {
	cookie := &http.Cookie{
		Name:     "gotify-client-token",
		Value:    token,
		Path:     "/",
		MaxAge:   sessionCookieMaxAge,
		HttpOnly: true,
		// Local Wails asset server is http://; Secure would prevent the cookie
		// from being stored. SameSite=Strict matches Gotify v3.
		SameSite: http.SameSiteStrictMode,
		Expires:  time.Now().Add(sessionCookieMaxAge * time.Second),
	}
	h.Add("Set-Cookie", cookie.String())
}

// injectSessionBootstrap inserts a head script that:
//  1. Seeds a non-HttpOnly cookie fallback (Set-Cookie is authoritative)
//  2. Rewrites /g/ → / via history.replaceState so Gotify v3 derives API base
//     as origin+/ (HashRouter keeps client routes in the hash)
func injectSessionBootstrap(body []byte, token string) []byte {
	inject := []byte(`<script>(function(){var t=` + strconv.Quote(token) + `;try{document.cookie='gotify-client-token='+encodeURIComponent(t)+'; path=/; max-age=604800; SameSite=Strict';}catch(e){}var p=location.pathname;if(p==='/g'||p.indexOf('/g/')===0){try{history.replaceState(null,'','/'+(location.search||'')+(location.hash||''));}catch(e){}}})();</script>`)
	lower := bytes.ToLower(body)
	if idx := bytes.Index(lower, []byte("<head")); idx >= 0 {
		if end := bytes.IndexByte(body[idx:], '>'); end >= 0 {
			at := idx + end + 1
			out := make([]byte, 0, len(body)+len(inject))
			out = append(out, body[:at]...)
			out = append(out, inject...)
			out = append(out, body[at:]...)
			return out
		}
	}
	return append(inject, body...)
}

//go:build windows

package notify

import (
	"fmt"
	"os"
	"os/exec"
	"path/filepath"
	"strings"
	"sync"
	"syscall"

	toast "git.sr.ht/~jackmordaunt/go-toast/v2"
)

const windowsAppID = "Gotify.Desktop"

var (
	windowsToastOnce sync.Once
	windowsToastErr  error
)

// showPlatformToast registers an AppUserModelID (required for unpackaged Win32
// toasts) and pushes a notification via go-toast / WinRT.
//
// Using the PowerShell AUMID alone often returns success with no visible toast
// when notifications for PowerShell are disabled or Focus Assist is on.
func showPlatformToast(title, body string) error {
	windowsToastOnce.Do(func() {
		windowsToastErr = ensureWindowsToastApp()
	})
	if windowsToastErr != nil {
		return windowsToastErr
	}

	n := toast.Notification{
		AppID: windowsAppID,
		Title: title,
		Body:  body,
		Audio: toast.Default,
	}
	if err := n.Push(); err != nil {
		return fmt.Errorf("windows toast: %w", err)
	}
	return nil
}

func ensureWindowsToastApp() error {
	exe, err := os.Executable()
	if err != nil {
		return fmt.Errorf("executable path: %w", err)
	}
	exe, err = filepath.Abs(exe)
	if err != nil {
		return fmt.Errorf("absolute executable path: %w", err)
	}

	if err := toast.SetAppData(toast.AppData{
		AppID:         windowsAppID,
		ActivationExe: exe,
	}); err != nil {
		return fmt.Errorf("register AppUserModelID: %w", err)
	}

	// Start Menu shortcut with System.AppUserModel.ID — required by Windows for
	// unpackaged desktop toast activation (Microsoft docs).
	if err := ensureStartMenuShortcut(exe); err != nil {
		return fmt.Errorf("start menu shortcut: %w", err)
	}
	return nil
}

func ensureStartMenuShortcut(exe string) error {
	appData := os.Getenv("APPDATA")
	if appData == "" {
		return fmt.Errorf("APPDATA not set")
	}
	lnk := filepath.Join(appData, "Microsoft", "Windows", "Start Menu", "Programs", "Gotify Desktop.lnk")
	if st, err := os.Stat(lnk); err == nil && !st.IsDir() {
		return nil
	}

	script := fmt.Sprintf(`
$ErrorActionPreference = 'Stop'
$WshShell = New-Object -ComObject WScript.Shell
$Shortcut = $WshShell.CreateShortcut(%s)
$Shortcut.TargetPath = %s
$Shortcut.WorkingDirectory = %s
$Shortcut.Description = 'Gotify Desktop'
$Shortcut.Save()
$shell = New-Object -ComObject Shell.Application
$folder = $shell.NameSpace(%s)
$item = $folder.ParseName(%s)
if ($null -eq $item) { throw 'shortcut not found after create' }
$item.ExtendedProperty('System.AppUserModel.ID') | Out-Null
# Set AUMID via PropertyStore (Shell.Application ExtendedProperty is read-only);
# use the documented PowerShell / COM approach with Windows API via shell link bytes.
Add-Type -TypeDefinition @"
using System;
using System.Runtime.InteropServices;
using System.Runtime.InteropServices.ComTypes;
public class ShortcutAumid {
  [ComImport, Guid("00021401-0000-0000-C000-000000000046")]
  class ShellLink { }
  [ComImport, InterfaceType(ComInterfaceType.InterfaceIsIUnknown), Guid("000214F9-0000-0000-C000-000000000046")]
  interface IShellLinkW {
    void GetPath([Out, MarshalAs(UnmanagedType.LPWStr)] System.Text.StringBuilder pszFile, int cchMaxPath, IntPtr pfd, uint fFlags);
    void GetIDList(out IntPtr ppidl);
    void SetIDList(IntPtr pidl);
    void GetDescription([Out, MarshalAs(UnmanagedType.LPWStr)] System.Text.StringBuilder pszName, int cchMaxName);
    void SetDescription([MarshalAs(UnmanagedType.LPWStr)] string pszName);
    void GetWorkingDirectory([Out, MarshalAs(UnmanagedType.LPWStr)] System.Text.StringBuilder pszDir, int cchMaxPath);
    void SetWorkingDirectory([MarshalAs(UnmanagedType.LPWStr)] string pszDir);
    void GetArguments([Out, MarshalAs(UnmanagedType.LPWStr)] System.Text.StringBuilder pszArgs, int cchMaxPath);
    void SetArguments([MarshalAs(UnmanagedType.LPWStr)] string pszArgs);
    void GetHotkey(out short pwHotkey);
    void SetHotkey(short wHotkey);
    void GetShowCmd(out int piShowCmd);
    void SetShowCmd(int iShowCmd);
    void GetIconLocation([Out, MarshalAs(UnmanagedType.LPWStr)] System.Text.StringBuilder pszIconPath, int cchIconPath, out int piIcon);
    void SetIconLocation([MarshalAs(UnmanagedType.LPWStr)] string pszIconPath, int iIcon);
    void SetRelativePath([MarshalAs(UnmanagedType.LPWStr)] string pszPathRel, uint dwReserved);
    void Resolve(IntPtr hwnd, uint fFlags);
    void SetPath([MarshalAs(UnmanagedType.LPWStr)] string pszFile);
  }
  [ComImport, InterfaceType(ComInterfaceType.InterfaceIsIUnknown), Guid("886D8EEB-8CF2-4446-8D02-CDBA1DBDCF99")]
  interface IPropertyStore {
    void GetCount(out uint cProps);
    void GetAt(uint iProp, out PROPERTYKEY pkey);
    void GetValue(ref PROPERTYKEY key, out PROPVARIANT pv);
    void SetValue(ref PROPERTYKEY key, ref PROPVARIANT pv);
    void Commit();
  }
  [StructLayout(LayoutKind.Sequential, Pack=4)]
  struct PROPERTYKEY { public Guid fmtid; public uint pid; }
  [StructLayout(LayoutKind.Sequential)]
  struct PROPVARIANT {
    public ushort vt;
    public ushort wReserved1, wReserved2, wReserved3;
    public IntPtr pointerValue;
  }
  public static void SetAumid(string lnkPath, string aumid) {
    var link = (IShellLinkW)new ShellLink();
    var file = (IPersistFile)link;
    file.Load(lnkPath, 0);
    var store = (IPropertyStore)link;
    var pk = new PROPERTYKEY{ fmtid = new Guid("9F4C2855-9F79-4B39-A8D0-E1D42DE1D5F3"), pid = 5 };
    var pv = new PROPVARIANT{ vt = 31, pointerValue = Marshal.StringToCoTaskMemUni(aumid) };
    store.SetValue(ref pk, ref pv);
    store.Commit();
    file.Save(lnkPath, true);
    Marshal.FreeCoTaskMem(pv.pointerValue);
  }
}
"@
[ShortcutAumid]::SetAumid(%s, %s)
`,
		psQuote(lnk),
		psQuote(exe),
		psQuote(filepath.Dir(exe)),
		psQuote(filepath.Dir(lnk)),
		psQuote(filepath.Base(lnk)),
		psQuote(lnk),
		psQuote(windowsAppID),
	)

	cmd := exec.Command("powershell.exe", "-NoProfile", "-NonInteractive", "-ExecutionPolicy", "Bypass", "-Command", script)
	cmd.SysProcAttr = &syscall.SysProcAttr{HideWindow: true}
	out, err := cmd.CombinedOutput()
	if err != nil {
		return fmt.Errorf("%w (%s)", err, strings.TrimSpace(string(out)))
	}
	return nil
}

func psQuote(s string) string {
	return "'" + strings.ReplaceAll(s, "'", "''") + "'"
}

