//go:build windows

package notify

import (
	"fmt"
	"os"
	"os/exec"
	"path/filepath"
	"strings"
	"sync"
	"syscall"
	"unsafe"

	toast "git.sr.ht/~jackmordaunt/go-toast/v2"
	"golang.org/x/sys/windows"
)

// Use the well-known PowerShell AUMID as a last-resort host identity, and our
// own AUMID when the Start Menu shortcut + registry registration succeed.
const (
	windowsAppID     = "Gotify.Desktop"
	powershellAppID  = `{1AC14E77-02E7-4E5D-B744-2EB1AE5198B7}\WindowsPowerShell\v1.0\powershell.exe`
)

var (
	windowsToastOnce sync.Once
	windowsToastErr  error
)

func showPlatformToast(title, body string) error {
	windowsToastOnce.Do(func() {
		windowsToastErr = ensureWindowsToastApp()
	})
	// Registration errors are non-fatal: we still try PowerShell-hosted toasts.
	_ = windowsToastErr

	var errs []string

	// 1) Our registered AUMID via go-toast (COM, then its own PS fallback).
	n := toast.Notification{
		AppID: windowsAppID,
		Title: title,
		Body:  body,
		Audio: toast.Default,
	}
	if err := n.Push(); err != nil {
		errs = append(errs, "gotify-aumid: "+err.Error())
	} else {
		return nil
	}

	// 2) Explicit PowerShell toast with our AUMID (in case COM no-oped silently).
	if err := powershellToast(windowsAppID, title, body); err != nil {
		errs = append(errs, "ps-gotify: "+err.Error())
	} else {
		return nil
	}

	// 3) PowerShell host AUMID — registered with Windows itself.
	if err := powershellToast(powershellAppID, title, body); err != nil {
		errs = append(errs, "ps-host: "+err.Error())
		return fmt.Errorf("windows toast failed: %s", strings.Join(errs, "; "))
	}
	return nil
}

func ensureWindowsToastApp() error {
	exe, err := os.Executable()
	if err != nil {
		return fmt.Errorf("executable path: %w", err)
	}
	exe, err = filepath.Abs(exe)
	if err != nil {
		return fmt.Errorf("absolute executable path: %w", err)
	}

	if err := toast.SetAppData(toast.AppData{
		AppID:         windowsAppID,
		ActivationExe: exe,
	}); err != nil {
		return fmt.Errorf("register AppUserModelID: %w", err)
	}
	if err := setCurrentProcessAUMID(windowsAppID); err != nil {
		return err
	}
	if err := ensureStartMenuShortcutWithAUMID(exe); err != nil {
		return fmt.Errorf("start menu shortcut: %w", err)
	}
	return nil
}

func setCurrentProcessAUMID(appID string) error {
	ptr, err := windows.UTF16PtrFromString(appID)
	if err != nil {
		return err
	}
	shell32 := windows.NewLazySystemDLL("shell32.dll")
	proc := shell32.NewProc("SetCurrentProcessExplicitAppUserModelID")
	hr, _, _ := proc.Call(uintptr(unsafe.Pointer(ptr)))
	if hr != 0 {
		return fmt.Errorf("SetCurrentProcessExplicitAppUserModelID: HRESULT 0x%X", hr)
	}
	return nil
}

func powershellToast(appID, title, body string) error {
	title = xmlEscape(title)
	body = xmlEscape(body)
	script := fmt.Sprintf(`
$ErrorActionPreference = 'Stop'
[Windows.UI.Notifications.ToastNotificationManager, Windows.UI.Notifications, ContentType = WindowsRuntime] | Out-Null
[Windows.Data.Xml.Dom.XmlDocument, Windows.Data.Xml.Dom.XmlDocument, ContentType = WindowsRuntime] | Out-Null
$xmlText = @'
<toast><visual><binding template="ToastGeneric"><text>%s</text><text>%s</text></binding></visual></toast>
'@
$xml = New-Object Windows.Data.Xml.Dom.XmlDocument
$xml.LoadXml($xmlText)
$toast = [Windows.UI.Notifications.ToastNotification]::new($xml)
[Windows.UI.Notifications.ToastNotificationManager]::CreateToastNotifier(%s).Show($toast)
`, title, body, psQuote(appID))

	cmd := exec.Command("powershell.exe", "-NoProfile", "-NonInteractive", "-ExecutionPolicy", "Bypass", "-Command", script)
	cmd.SysProcAttr = &syscall.SysProcAttr{HideWindow: true}
	out, err := cmd.CombinedOutput()
	if err != nil {
		return fmt.Errorf("%w (%s)", err, strings.TrimSpace(string(out)))
	}
	return nil
}

func ensureStartMenuShortcutWithAUMID(exe string) error {
	appData := os.Getenv("APPDATA")
	if appData == "" {
		return fmt.Errorf("APPDATA not set")
	}
	dir := filepath.Join(appData, "Microsoft", "Windows", "Start Menu", "Programs")
	lnk := filepath.Join(dir, "Gotify Desktop.lnk")
	if err := os.MkdirAll(dir, 0o755); err != nil {
		return err
	}

	// Always (re)write the shortcut so the AUMID property is present — a bare
	// WScript.Shell .lnk without System.AppUserModel.ID is why toasts stay silent.
	script := fmt.Sprintf(`
$ErrorActionPreference = 'Stop'
$exe = %s
$lnkPath = %s
$aumid = %s
$WshShell = New-Object -ComObject WScript.Shell
$Shortcut = $WshShell.CreateShortcut($lnkPath)
$Shortcut.TargetPath = $exe
$Shortcut.WorkingDirectory = [System.IO.Path]::GetDirectoryName($exe)
$Shortcut.Description = 'Gotify Desktop'
$Shortcut.Save()

$bytes = [System.IO.File]::ReadAllBytes($lnkPath)
# Shortcut property store for System.AppUserModel.ID is not writable via WScript.
# Use Shell.Application's Folder.GetDetailsOf is read-only; use PowerShell +
# Windows API via late-bound PropertyStore on the .lnk through a tiny C# helper.
Add-Type -Namespace GotifyDesktop -Name Shortcut -MemberDefinition @"
using System;
using System.Runtime.InteropServices;
using System.Runtime.InteropServices.ComTypes;
public static class AumidShortcut {
  [DllImport("ole32.dll")] static extern int CoCreateInstance(ref Guid clsid, IntPtr outer, uint ctx, ref Guid iid, out IntPtr ppv);
  static Guid CLSID_ShellLink = new Guid("00021401-0000-0000-C000-000000000046");
  static Guid IID_IShellLinkW = new Guid("000214F9-0000-0000-C000-000000000046");
  static Guid IID_IPersistFile = new Guid("0000010b-0000-0000-C000-000000000046");
  static Guid IID_IPropertyStore = new Guid("886D8EEB-8CF2-4446-8D02-CDBA1DBDCF99");
  [StructLayout(LayoutKind.Sequential, Pack=4)] struct PROPERTYKEY { public Guid fmtid; public uint pid; }
  [StructLayout(LayoutKind.Sequential)] struct PROPVARIANT {
    public ushort vt; public ushort w1,w2,w3; public IntPtr val;
  }
  [ComImport, InterfaceType(ComInterfaceType.InterfaceIsIUnknown), Guid("000214F9-0000-0000-C000-000000000046")]
  interface IShellLinkW {
    void _VtblGap0_18(); // skip 18 methods we don't need
    void SetPath([MarshalAs(UnmanagedType.LPWStr)] string pszFile);
  }
  // Using full IShellLink is fragile with _VtblGap; prefer WScript for path and
  // only set AUMID via IPropertyStore obtained from the loaded ShellLink.
  [ComImport, InterfaceType(ComInterfaceType.InterfaceIsIUnknown), Guid("886D8EEB-8CF2-4446-8D02-CDBA1DBDCF99")]
  interface IPropertyStore {
    uint GetCount();
    void GetAt(uint iProp, out PROPERTYKEY pkey);
    void GetValue(ref PROPERTYKEY key, out PROPVARIANT pv);
    void SetValue(ref PROPERTYKEY key, ref PROPVARIANT pv);
    void Commit();
  }
  public static void Set(string lnk, string aumid) {
    Type t = Type.GetTypeFromCLSID(CLSID_ShellLink);
    object link = Activator.CreateInstance(t);
    IPersistFile pf = (IPersistFile)link;
    pf.Load(lnk, 0);
    IPropertyStore ps = (IPropertyStore)link;
    PROPERTYKEY pk = new PROPERTYKEY();
    pk.fmtid = new Guid("9F4C2855-9F79-4B39-A8D0-E1D42DE1D5F3");
    pk.pid = 5; // System.AppUserModel.ID
    PROPVARIANT pv = new PROPVARIANT();
    pv.vt = 31; // VT_LPWSTR
    pv.val = Marshal.StringToCoTaskMemUni(aumid);
    ps.SetValue(ref pk, ref pv);
    ps.Commit();
    pf.Save(lnk, true);
    Marshal.FreeCoTaskMem(pv.val);
  }
}
"@ -ErrorAction SilentlyContinue
if (-not ([System.Management.Automation.PSTypeName]'AumidShortcut').Type) {
  Add-Type -TypeDefinition @"
using System;
using System.Runtime.InteropServices;
using System.Runtime.InteropServices.ComTypes;
public static class AumidShortcut {
  static Guid CLSID_ShellLink = new Guid("00021401-0000-0000-C000-000000000046");
  [StructLayout(LayoutKind.Sequential, Pack=4)] struct PROPERTYKEY { public Guid fmtid; public uint pid; }
  [StructLayout(LayoutKind.Sequential)] struct PROPVARIANT {
    public ushort vt; public ushort w1,w2,w3; public IntPtr val;
  }
  [ComImport, InterfaceType(ComInterfaceType.InterfaceIsIUnknown), Guid("886D8EEB-8CF2-4446-8D02-CDBA1DBDCF99")]
  interface IPropertyStore {
    uint GetCount();
    void GetAt(uint iProp, out PROPERTYKEY pkey);
    void GetValue(ref PROPERTYKEY key, out PROPVARIANT pv);
    void SetValue(ref PROPERTYKEY key, ref PROPVARIANT pv);
    void Commit();
  }
  public static void Set(string lnk, string aumid) {
    Type t = Type.GetTypeFromCLSID(CLSID_ShellLink);
    object link = Activator.CreateInstance(t);
    IPersistFile pf = (IPersistFile)link;
    pf.Load(lnk, 0);
    IPropertyStore ps = (IPropertyStore)link;
    PROPERTYKEY pk = new PROPERTYKEY();
    pk.fmtid = new Guid("9F4C2855-9F79-4B39-A8D0-E1D42DE1D5F3");
    pk.pid = 5;
    PROPVARIANT pv = new PROPVARIANT();
    pv.vt = 31;
    pv.val = Marshal.StringToCoTaskMemUni(aumid);
    ps.SetValue(ref pk, ref pv);
    ps.Commit();
    pf.Save(lnk, true);
    Marshal.FreeCoTaskMem(pv.val);
  }
}
"@
}
[AumidShortcut]::Set($lnkPath, $aumid)
`, psQuote(exe), psQuote(lnk), psQuote(windowsAppID))

	cmd := exec.Command("powershell.exe", "-NoProfile", "-NonInteractive", "-ExecutionPolicy", "Bypass", "-Command", script)
	cmd.SysProcAttr = &syscall.SysProcAttr{HideWindow: true}
	out, err := cmd.CombinedOutput()
	if err != nil {
		return fmt.Errorf("%w (%s)", err, strings.TrimSpace(string(out)))
	}
	return nil
}

func psQuote(s string) string {
	return "'" + strings.ReplaceAll(s, "'", "''") + "'"
}

func xmlEscape(s string) string {
	r := strings.NewReplacer(
		`&`, "&amp;",
		`<`, "&lt;",
		`>`, "&gt;",
		`"`, "&quot;",
		`'`, "&apos;",
	)
	return r.Replace(s)
}

