import './style.css';
import {Connect, GetStatus, GetClientToken, GetUIPath} from '../wailsjs/go/main/App';
import {EventsOn} from '../wailsjs/runtime/runtime';

const setupView = document.getElementById('setup-view');
const gotifyView = document.getElementById('gotify-view');
const frame = document.getElementById('gotify-frame');
const form = document.getElementById('setup-form');
const errorEl = document.getElementById('error');
const statusLine = document.getElementById('status-line');
const connectBtn = document.getElementById('connect-btn');
const serverInput = document.getElementById('server-url');
const usernameInput = document.getElementById('username');

/** @type {'setup'|'gotify'|null} */
let currentView = null;
let bootstrapped = false;

function showError(msg) {
  if (!msg) {
    errorEl.hidden = true;
    errorEl.textContent = '';
    return;
  }
  errorEl.hidden = false;
  errorEl.textContent = msg;
}

function applySession(token) {
  if (!token) return;
  try {
    document.cookie = `gotify-client-token=${encodeURIComponent(token)}; path=/; max-age=604800; SameSite=Lax`;
  } catch (_) {
    /* ignore */
  }
}

function showSetup(status) {
  currentView = 'setup';
  setupView.hidden = false;
  gotifyView.hidden = true;
  if (status?.serverUrl) {
    serverInput.value = status.serverUrl;
  }
  if (status?.username && usernameInput) {
    usernameInput.value = status.username;
  }
  frame.src = 'about:blank';
  updateStatusLine(status);
}

async function showGotify(payload, {forceReload = false} = {}) {
  let token = payload?.token;
  let uiPath = payload?.uiPath;
  if (!token) {
    token = await GetClientToken();
  }
  if (!uiPath) {
    uiPath = await GetUIPath();
  }
  applySession(token);

  const alreadyShowing = currentView === 'gotify' && !gotifyView.hidden;
  currentView = 'gotify';
  setupView.hidden = true;
  gotifyView.hidden = false;

  // Do not reload the iframe on every stream status tick — that wiped the Gotify session.
  if (!forceReload && alreadyShowing && frame.src && !frame.src.endsWith('about:blank')) {
    return;
  }
  frame.src = `${uiPath}${uiPath.includes('?') ? '&' : '?'}_=${Date.now()}`;
}

function updateStatusLine(status) {
  if (!status) {
    statusLine.textContent = '';
    return;
  }
  const parts = [];
  if (status.configured) {
    parts.push(status.connected ? 'Stream connected' : 'Stream disconnected');
  } else {
    parts.push('Not configured');
  }
  if (status.notifyReady === false) {
    parts.push('Notify: fallback');
  }
  if (status.notifyError) {
    parts.push('Notify error: ' + status.notifyError);
  }
  if (status.error) {
    parts.push(status.error);
  }
  statusLine.textContent = parts.join(' · ');
}

async function applyStatus(status) {
  if (!status) return;
  // Once we know a saved session exists, never fall back to the Connect form
  // from a late/racy status tick — Settings is the only way back.
  if (status.view === 'gotify' && status.configured) {
    bootstrapped = true;
    await showGotify(null, {forceReload: false});
  } else if (status.configured && bootstrapped && currentView === 'gotify') {
    updateStatusLine(status);
    return;
  } else if (!status.configured || status.view === 'setup') {
    if (currentView !== 'setup') {
      showSetup(status);
    } else {
      updateStatusLine(status);
      return;
    }
  } else {
    updateStatusLine(status);
    return;
  }
  updateStatusLine(status);
}

function postToGotify(msg) {
  try {
    frame?.contentWindow?.postMessage(msg, '*');
  } catch (_) {
    /* ignore */
  }
}

async function shellNotify(title, body) {
  try {
    if (!('Notification' in window)) return;
    if (Notification.permission === 'default') {
      await Notification.requestPermission();
    }
    if (Notification.permission === 'granted') {
      new Notification(title || 'Gotify', {body: body || '', silent: false});
    }
  } catch (err) {
    console.warn('shell Notification failed', err);
  }
}

form.addEventListener('submit', async (event) => {
  event.preventDefault();
  showError('');
  connectBtn.disabled = true;
  connectBtn.textContent = 'Connecting…';
  const serverUrl = serverInput.value.trim();
  const username = usernameInput.value;
  const password = document.getElementById('password').value;
  try {
    await Connect(serverUrl, username, password);
    document.getElementById('password').value = '';
    bootstrapped = true;
    await showGotify(null, {forceReload: true});
  } catch (err) {
    showError(String(err));
  } finally {
    connectBtn.disabled = false;
    connectBtn.textContent = 'Connect';
  }
});

EventsOn('status', (status) => {
  applyStatus(status).catch(console.error);
});
EventsOn('show-setup', () => {
  bootstrapped = false;
  GetStatus().then(showSetup).catch(console.error);
});
EventsOn('show-gotify', (payload) => {
  bootstrapped = true;
  showGotify(payload, {forceReload: true}).catch(console.error);
});
EventsOn('gotify-message', (payload) => {
  postToGotify({type: 'gotify-desktop-refresh'});
  shellNotify(payload?.title, payload?.body).catch(console.warn);
});

async function bootstrap() {
  // Hide the Connect form until we know whether a session already exists.
  setupView.hidden = true;
  for (let i = 0; i < 8; i++) {
    try {
      const status = await GetStatus();
      if (status?.configured && status.view === 'gotify') {
        bootstrapped = true;
        await showGotify(null, {forceReload: true});
        updateStatusLine(status);
        return;
      }
      if (status && !status.configured) {
        showSetup(status);
        return;
      }
      // Startup still loading config — wait briefly.
      await new Promise((r) => setTimeout(r, 100));
    } catch (err) {
      console.error(err);
    }
  }
  try {
    const status = await GetStatus();
    await applyStatus(status);
  } catch (err) {
    console.error(err);
    showSetup(null);
  }
}

bootstrap().catch(console.error);

//go:build windows

package notify

import (
	"fmt"
	"os"
	"os/exec"
	"path/filepath"
	"strings"
	"sync"
	"syscall"
	"unsafe"

	"github.com/elpatron68/gotify-desktop/internal/applog"
	toast "git.sr.ht/~jackmordaunt/go-toast/v2"
	"golang.org/x/sys/windows"
)

const (
	windowsAppID = "Gotify.Desktop"
	// Explorer's toast host is almost always allowed to show banners.
	explorerAppID = `Microsoft.Windows.Explorer`
	powershellAppID = `{1AC14E77-02E7-4E5D-B744-2EB1AE5198B7}\WindowsPowerShell\v1.0\powershell.exe`
)

var (
	windowsToastOnce sync.Once
	windowsRegErr    error
)

func showPlatformToast(title, body string) error {
	windowsToastOnce.Do(func() {
		windowsRegErr = ensureWindowsToastApp()
		if windowsRegErr != nil {
			applog.Printf("toast register: %v", windowsRegErr)
		} else {
			applog.Printf("toast register: AUMID=%s ok", windowsAppID)
		}
	})

	// Prefer hosts Windows already trusts for banners. Custom AUMIDs often report
	// Setting=Enabled while producing no visible toast on unpackaged Win32 apps.
	attempts := []struct {
		name  string
		appID string
	}{
		{"explorer-host", explorerAppID},
		{"powershell-host", powershellAppID},
		{"gotify-aumid", windowsAppID},
	}

	var errs []string
	var anyOK bool
	for _, a := range attempts {
		applog.Printf("toast try method=%s appID=%s title=%q", a.name, a.appID, title)
		if err := powershellToast(a.appID, title, body); err != nil {
			applog.Printf("toast fail method=%s: %v", a.name, err)
			errs = append(errs, a.name+": "+err.Error())
			continue
		}
		applog.Printf("toast Show() returned ok method=%s", a.name)
		anyOK = true
		// Explorer/PowerShell hosts are the ones users actually see — stop there.
		if a.name != "gotify-aumid" {
			return nil
		}
	}

	// Native go-toast as an extra channel (uses the registered AUMID + shortcut).
	if err := goToastPush(title, body); err != nil {
		applog.Printf("toast go-toast Push failed: %v", err)
		errs = append(errs, "go-toast: "+err.Error())
	} else {
		applog.Printf("toast go-toast Push ok")
		anyOK = true
	}

	if anyOK {
		return nil
	}
	return fmt.Errorf("windows toast failed: %s", strings.Join(errs, "; "))
}

func goToastPush(title, body string) error {
	n := toast.Notification{
		AppID: windowsAppID,
		Title: title,
		Body:  body,
	}
	return n.Push()
}

func ensureWindowsToastApp() error {
	exe, err := os.Executable()
	if err != nil {
		return err
	}
	exe, err = filepath.Abs(exe)
	if err != nil {
		return err
	}
	applog.Printf("toast exe=%s", exe)
	if err := toast.SetAppData(toast.AppData{
		AppID:         windowsAppID,
		ActivationExe: exe,
	}); err != nil {
		return err
	}
	if err := setCurrentProcessAUMID(windowsAppID); err != nil {
		return err
	}
	if err := ensureStartMenuShortcut(exe); err != nil {
		applog.Printf("toast shortcut: %v", err)
	} else {
		applog.Printf("toast shortcut ensured under Start Menu\\Programs\\Gotify Desktop.lnk")
	}
	return nil
}

func setCurrentProcessAUMID(appID string) error {
	ptr, err := windows.UTF16PtrFromString(appID)
	if err != nil {
		return err
	}
	shell32 := windows.NewLazySystemDLL("shell32.dll")
	proc := shell32.NewProc("SetCurrentProcessExplicitAppUserModelID")
	hr, _, _ := proc.Call(uintptr(unsafe.Pointer(ptr)))
	if hr != 0 {
		return fmt.Errorf("SetCurrentProcessExplicitAppUserModelID: HRESULT 0x%X", hr)
	}
	return nil
}

func powershellToast(appID, title, body string) error {
	script := fmt.Sprintf(`
$ErrorActionPreference = 'Stop'
[Windows.UI.Notifications.ToastNotificationManager, Windows.UI.Notifications, ContentType = WindowsRuntime] | Out-Null
[Windows.Data.Xml.Dom.XmlDocument, Windows.Data.Xml.Dom.XmlDocument, ContentType = WindowsRuntime] | Out-Null
$xmlText = @'
<toast><visual><binding template="ToastGeneric"><text>%s</text><text>%s</text></binding></visual><audio src="ms-winsoundevent:Notification.Default"/></toast>
'@
$xml = New-Object Windows.Data.Xml.Dom.XmlDocument
$xml.LoadXml($xmlText)
$toast = [Windows.UI.Notifications.ToastNotification]::new($xml)
$n = [Windows.UI.Notifications.ToastNotificationManager]::CreateToastNotifier(%s)
$n.Show($toast)
Write-Output ('notifier_ok setting=' + $n.Setting)
`, xmlEscape(title), xmlEscape(body), psQuote(appID))

	cmd := exec.Command("powershell.exe", "-NoProfile", "-NonInteractive", "-ExecutionPolicy", "Bypass", "-Command", script)
	cmd.SysProcAttr = &syscall.SysProcAttr{HideWindow: true}
	out, err := cmd.CombinedOutput()
	trimmed := strings.TrimSpace(string(out))
	if trimmed != "" {
		applog.Printf("toast powershell output: %s", trimmed)
	}
	if err != nil {
		return fmt.Errorf("%w (%s)", err, trimmed)
	}
	// Setting enum: 0=Enabled, 1=DisabledForApplication, 2=DisabledForUser, 3=DisabledByGroupPolicy, 4=DisabledByManifest
	if strings.Contains(trimmed, "setting=1") || strings.Contains(trimmed, "setting=2") {
		return fmt.Errorf("notifications disabled for this app (%s)", trimmed)
	}
	return nil
}

