package i18n

import (
	"encoding/json"
	"fmt"
	"io/fs"
	"sort"

	"embed"
)

//go:embed locales/*.json
var localeFS embed.FS

// Language is a selectable UI locale.
type Language struct {
	Code string // e.g. "de"
	Name string // native endonym, e.g. "Deutsch"
}

// preferredOrder is the menu order for known languages.
var preferredOrder = []string{"en", "de", "fr", "es"}

// endonyms are fixed native names (not translated).
var endonyms = map[string]string{
	"en": "English",
	"de": "Deutsch",
	"fr": "Français",
	"es": "Español",
}

func load(lang string) (Catalog, error) {
	name := "locales/" + lang + ".json"
	data, err := localeFS.ReadFile(name)
	if err != nil {
		return nil, fmt.Errorf("%s: %w", name, err)
	}
	var cat Catalog
	if err := json.Unmarshal(data, &cat); err != nil {
		return nil, err
	}
	return cat, nil
}

// Supported returns language codes that have a catalog file.
func Supported() []string {
	entries, err := fs.ReadDir(localeFS, "locales")
	if err != nil {
		return []string{"en"}
	}
	have := map[string]bool{}
	for _, e := range entries {
		name := e.Name()
		if len(name) > 5 && name[len(name)-5:] == ".json" {
			have[name[:len(name)-5]] = true
		}
	}
	var out []string
	for _, code := range preferredOrder {
		if have[code] {
			out = append(out, code)
			delete(have, code)
		}
	}
	var rest []string
	for code := range have {
		rest = append(rest, code)
	}
	sort.Strings(rest)
	return append(out, rest...)
}

// Languages returns supported locales with native display names for menus.
func Languages() []Language {
	codes := Supported()
	out := make([]Language, 0, len(codes))
	for _, code := range codes {
		name := endonyms[code]
		if name == "" {
			name = code
		}
		out = append(out, Language{Code: code, Name: name})
	}
	return out
}

package tray

// Callbacks wired by the application.
type Callbacks struct {
	OnOpen      func()
	OnSettings  func()
	OnAutostart func()
	OnLanguage  func(code string)
	OnQuit      func()
}

// Options configures initial tray menu state.
type Options struct {
	AutostartEnabled bool
	Locale           string
	Languages        []Language
	Labels           Labels
}

// Language is a tray language menu entry.
type Language struct {
	Code string
	Name string
}

// Labels are localized tray strings (resolved by the app via i18n).
type Labels struct {
	Tooltip          string
	StatusStarting   string
	StatusTooltip    string
	Open             string
	OpenTooltip      string
	Settings         string
	SettingsTooltip  string
	Autostart        string
	AutostartTooltip string
	Language         string
	LanguageTooltip  string
	Quit             string
	QuitTooltip      string
}

//go:build !darwin

package tray

import (
	"sync"

	"fyne.io/systray"
)

// Controller manages the system tray icon and menu.
type Controller struct {
	icon []byte
	cb   Callbacks
	opts Options

	mu            sync.Mutex
	statusItem    *systray.MenuItem
	openItem      *systray.MenuItem
	settingsItem  *systray.MenuItem
	autostartItem *systray.MenuItem
	languageItem  *systray.MenuItem
	quitItem      *systray.MenuItem
	langItems     map[string]*systray.MenuItem
	started       bool
}

// New creates a tray controller. icon should be PNG bytes (Linux) or ICO (Windows).
func New(icon []byte, cb Callbacks, opts Options) *Controller {
	return &Controller{icon: icon, cb: cb, opts: opts, langItems: map[string]*systray.MenuItem{}}
}

// Start runs the systray event loop in a background goroutine.
func (c *Controller) Start() {
	c.mu.Lock()
	if c.started {
		c.mu.Unlock()
		return
	}
	c.started = true
	c.mu.Unlock()
	go systray.Run(c.onReady, c.onExit)
}

// Stop quits the systray loop.
func (c *Controller) Stop() {
	systray.Quit()
}

// SetStatus updates the status menu label.
func (c *Controller) SetStatus(text string) {
	c.mu.Lock()
	item := c.statusItem
	c.mu.Unlock()
	if item != nil {
		item.SetTitle(text)
	}
}

// SetAutostartChecked updates the Start at login checkbox.
func (c *Controller) SetAutostartChecked(enabled bool) {
	c.mu.Lock()
	item := c.autostartItem
	c.mu.Unlock()
	if item == nil {
		return
	}
	if enabled {
		item.Check()
	} else {
		item.Uncheck()
	}
}

// SetLabels refreshes tray menu titles after a locale change.
func (c *Controller) SetLabels(l Labels) {
	c.mu.Lock()
	c.opts.Labels = l
	status, open, settings := c.statusItem, c.openItem, c.settingsItem
	autostart, language, quit := c.autostartItem, c.languageItem, c.quitItem
	c.mu.Unlock()

	if l.Tooltip != "" {
		systray.SetTooltip(l.Tooltip)
	}
	if status != nil && l.StatusStarting != "" {
		// Keep current status text if it was customized; only update tooltip-bearing static labels.
		_ = status
	}
	if open != nil {
		open.SetTitle(or(l.Open, open.String()))
	}
	if settings != nil {
		settings.SetTitle(or(l.Settings, "Settings"))
	}
	if autostart != nil {
		autostart.SetTitle(or(l.Autostart, "Start at login"))
	}
	if language != nil {
		language.SetTitle(or(l.Language, "Language"))
	}
	if quit != nil {
		quit.SetTitle(or(l.Quit, "Quit"))
	}
}

// SetLocaleChecked marks the active language in the submenu.
func (c *Controller) SetLocaleChecked(code string) {
	c.mu.Lock()
	items := c.langItems
	c.opts.Locale = code
	c.mu.Unlock()
	for id, item := range items {
		if item == nil {
			continue
		}
		if id == code {
			item.Check()
		} else {
			item.Uncheck()
		}
	}
}

func (c *Controller) onReady() {
	l := c.opts.Labels
	tooltip := l.Tooltip
	if tooltip == "" {
		tooltip = "Gotify Desktop"
	}
	systray.SetTooltip(tooltip)
	if len(c.icon) > 0 {
		systray.SetTemplateIcon(c.icon, c.icon)
		systray.SetIcon(c.icon)
	}
	systray.SetTitle("")

	status := systray.AddMenuItem(or(l.StatusStarting, "Status: starting…"), or(l.StatusTooltip, "Connection status"))
	status.Disable()

	systray.AddSeparator()
	open := systray.AddMenuItem(or(l.Open, "Open window"), or(l.OpenTooltip, "Show the Gotify window"))
	settings := systray.AddMenuItem(or(l.Settings, "Settings"), or(l.SettingsTooltip, "Open connection settings"))
	autostart := systray.AddMenuItemCheckbox(
		or(l.Autostart, "Start at login"),
		or(l.AutostartTooltip, "Launch Gotify Desktop when you log in"),
		c.opts.AutostartEnabled,
	)
	language := systray.AddMenuItem(or(l.Language, "Language"), or(l.LanguageTooltip, "Choose the interface language"))

	langItems := map[string]*systray.MenuItem{}
	for _, lang := range c.opts.Languages {
		item := language.AddSubMenuItemCheckbox(lang.Name, lang.Name, lang.Code == c.opts.Locale)
		langItems[lang.Code] = item
	}

	systray.AddSeparator()
	quit := systray.AddMenuItem(or(l.Quit, "Quit"), or(l.QuitTooltip, "Exit Gotify Desktop"))

	c.mu.Lock()
	c.statusItem = status
	c.openItem = open
	c.settingsItem = settings
	c.autostartItem = autostart
	c.languageItem = language
	c.quitItem = quit
	c.langItems = langItems
	c.mu.Unlock()

	go func() {
		for {
			select {
			case <-open.ClickedCh:
				if c.cb.OnOpen != nil {
					c.cb.OnOpen()
				}
			case <-settings.ClickedCh:
				if c.cb.OnSettings != nil {
					c.cb.OnSettings()
				}
			case <-autostart.ClickedCh:
				if c.cb.OnAutostart != nil {
					c.cb.OnAutostart()
				}
			case <-quit.ClickedCh:
				if c.cb.OnQuit != nil {
					c.cb.OnQuit()
				}
				systray.Quit()
				return
			}
		}
	}()

	for code, item := range langItems {
		code, item := code, item
		go func() {
			for range item.ClickedCh {
				if c.cb.OnLanguage != nil {
					c.cb.OnLanguage(code)
				}
			}
		}()
	}
}

func (c *Controller) onExit() {}

func or(v, fallback string) string {
	if v != "" {
		return v
	}
	return fallback
}

